# Generated by scripts/formula.sh in tyldra/keynook; the release workflow
# updates it. Edit the script there, not this file.
class Keynook < Formula
  desc "API key manager for the Mac terminal, backed by the login Keychain"
  homepage "https://github.com/tyldra/keynook"
  url "https://github.com/tyldra/keynook/releases/download/v0.3.1/keynook-0.3.1-macos.tar.gz"
  sha256 "edc195a3b02afbd9ab3d78fc0b2c73a8853573888e96916b183c78d4612dea37"
  license "Apache-2.0"

  livecheck do
    url :stable
    strategy :github_latest
  end

  depends_on macos: :sequoia

  # The release archive holds a universal binary, built and attested by the
  # release workflow from the tagged commit; there is nothing to compile.
  def install
    bin.install "keynook"
    generate_completions_from_executable(bin/"keynook", "--generate-completion-script")
  end

  def caveats
    <<~EOS
      Connect Keynook to your shell and to apps:
        echo 'eval "$(keynook init zsh)"' >> ~/.zshrc
        keynook agent install
        keynook doctor

      Before uninstalling, run keynook agent uninstall. Your keys stay in the
      login Keychain after an uninstall; to delete them too, run
      keynook remove NAME for each key first.
    EOS
  end

  test do
    assert_equal version.to_s, shell_output("#{bin}/keynook --version").strip
    ENV["KEYNOOK_CONFIG_DIR"] = testpath/"config"
    ENV["KEYNOOK_SERVICE_PREFIX"] = "keynook-brew-test"
    assert_match "No keys yet", shell_output("#{bin}/keynook list 2>&1")
  end
end
